WITH rev_per_client AS ( SELECT "Razão Social" AS cliente, SUM(faturamento) AS rev FROM pedidos_efetivos GROUP BY cliente ), rev_with_cum AS ( SELECT cliente, rev, SUM(rev) OVER (ORDER BY rev DESC) AS cum_rev, ROW_NUMBER() OVER (ORDER BY rev DESC) AS rn FROM rev_per_client ), total_rev AS ( SELECT SUM(rev) AS total_rev FROM rev_per_client ) SELECT MIN(rn) AS clientes_80_percent FROM rev_with_cum, total_rev WHERE cum_rev >= 0.8 * total_rev;